file_put_contents($dir.'refractive-index-calc.blade.php',t('fas fa-eye','Refractive Index Calc','Calculate angles using Snell\'s law','<div class="row g-3"><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">n₁</label><input type="number" id="in-n1" class="form-control form-control-lg" value="1.0" step="0.01"><div class="form-text">Air=1.0</div></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">θ₁ (degrees)</label><input type="number" id="in-t1" class="form-control form-control-lg" value="30" step="0.1"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">n₂</label><input type="number" id="in-n2" class="form-control form-control-lg" value="1.5" step="0.01"><div class="form-text">Glass=1.5</div></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">θ₂ (degrees)</label><input type="number" id="in-t2" class="form-control form-control-lg" value="" placeholder="solve"></div></div>','<b>Snell\'s Law:</b> n₁ sin(θ₁) = n₂ sin(θ₂)','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var n1=parseFloat(document.getElementById("in-n1").value)||1,t1=document.getElementById("in-t1").value,n2=parseFloat(document.getElementById("in-n2").value)||1,t2=document.getElementById("in-t2").value;var result,label;if(!t2||t2===""){var a1=parseFloat(t1)*Math.PI/180;var sinT2=n1*Math.sin(a1)/n2;if(Math.abs(sinT2)>1){document.getElementById("out-main").textContent="Total Internal Reflection";document.getElementById("out-unit").textContent="Critical angle exceeded";document.getElementById("out-ins").innerHTML="<p class=\\"text-danger\\">sin(θ₂) > 1 — total internal reflection occurs</p>";document.getElementById("res").classList.remove("d-none");return;}result=Math.asin(sinT2)*180/Math.PI;label="θ₂ = "+result.toFixed(2)+"°";}else{var a2=parseFloat(t2)*Math.PI/180;result=Math.asin(n2*Math.sin(a2)/n1)*180/Math.PI;label="θ₁ = "+result.toFixed(2)+"°";}document.getElementById("out-main").textContent=result.toFixed(2)+"°";document.getElementById("out-unit").textContent=label;var crit=Math.asin(Math.min(1,n2>n1?1:n1>n2?n2/n1:1))*180/Math.PI;document.getElementById("out-detail").innerHTML=\'<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">n₁</div><div class="h5 fw-bold mb-0 text-primary">\'+n1+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">n₂</div><div class="h5 fw-bold mb-0 text-info">\'+n2+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Critical Angle</div><div class="h5 fw-bold mb-0 text-warning">\'+(n1>n2?crit.toFixed(2)+"°":"N/A")+\'</div></div></div>\';document.getElementById("out-ins").innerHTML="<p>"+label+" via Snell\'s Law</p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-n1").value=1;document.getElementById("in-t1").value=30;document.getElementById("in-n2").value=1.5;document.getElementById("in-t2").value="";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
