file_put_contents($dir.'sourdough-bakers-calc.blade.php',t('fas fa-bread-slice','Sourdough Bakers Calc','Calculate baker\'s percentages and hydration','<div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Flour (g)</label><input type="number" id="in-flour" class="form-control form-control-lg" value="500" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Water (g)</label><input type="number" id="in-water" class="form-control form-control-lg" value="350" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Salt (g)</label><input type="number" id="in-salt" class="form-control form-control-lg" value="10" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Starter (g)</label><input type="number" id="in-starter" class="form-control form-control-lg" value="100" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Hydration %</label><input type="number" id="in-hydration" class="form-control form-control-lg" value="" placeholder="auto" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Flour Type</label><select id="in-type" class="form-select form-select-lg"><option value="bread">Bread Flour</option><option value="ap">All Purpose</option><option value="whole">Whole Wheat</option><option value="rye">Rye</option></select></div></div>','<b>Baker\'s %:</b> All ingredients as percentage of total flour weight','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var flour=parseFloat(document.getElementById("in-flour").value)||0,water=parseFloat(document.getElementById("in-water").value)||0,salt=parseFloat(document.getElementById("in-salt").value)||0,starter=parseFloat(document.getElementById("in-starter").value)||0;if(flour===0)return;var starterFlour=starter*0.5,starterWater=starter*0.5;var totalFlour=flour+starterFlour;var totalWater=water+starterWater;var hydration=(totalWater/totalFlour)*100;var saltPct=(salt/totalFlour)*100;var starterPct=(starter/flour)*100;var total=flour+water+salt+starter;document.getElementById("out-main").textContent=hydration.toFixed(1)+"%";document.getElementById("out-unit").textContent="Total Hydration";document.getElementById("out-detail").innerHTML=\'<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Total Dough</div><div class="h5 fw-bold mb-0 text-primary">\'+total+\' g</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Salt %</div><div class="h5 fw-bold mb-0 text-info">\'+saltPct.toFixed(1)+\'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Starter %</div><div class="h5 fw-bold mb-0 text-warning">\'+starterPct.toFixed(1)+\'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Total Flour</div><div class="h5 fw-bold mb-0 text-success">\'+totalFlour.toFixed(0)+\' g</div></div></div>\';var ins=["Hydration: <b>"+hydration.toFixed(1)+"%</b> (includes starter water)"];if(hydration>80)ins.push("High hydration — expect an open crumb but sticky dough");else if(hydration<65)ins.push("Low hydration — denser crumb, easier to handle");if(saltPct<1.5)ins.push("⚠ Salt is low — consider 1.8-2.2% for flavor");document.getElementById("out-ins").innerHTML=\'<ul class="list-unstyled mb-0">\'+ins.map(function(x){return\'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>\'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-flour").value=500;document.getElementById("in-water").value=350;document.getElementById("in-salt").value=10;document.getElementById("in-starter").value=100;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Hydration: "+document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
