file_put_contents($dir.'coffee-brew-optimizer.blade.php',t('fas fa-mug-hot','Coffee Brew Optimizer','Optimize brew ratio, extraction yield, and grind size','<div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Coffee (g)</label><input type="number" id="in-coffee" class="form-control form-control-lg" value="18" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Water (g)</label><input type="number" id="in-water" class="form-control form-control-lg" value="300" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Brew Method</label><select id="in-method" class="form-select form-select-lg"><option value="pourover">Pour Over</option><option value="french">French Press</option><option value="espresso">Espresso</option><option value="aeropress">AeroPress</option></select></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Grind Size</label><select id="in-grind" class="form-select form-select-lg"><option value="fine">Fine</option><option value="medium" selected>Medium</option><option value="coarse">Coarse</option></select></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Water Temp (°C)</label><input type="number" id="in-temp" class="form-control form-control-lg" value="96" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">TDS % (optional)</label><input type="number" id="in-tds" class="form-control form-control-lg" value="1.35" step="0.01"></div></div>','<b>SCA Standard:</b> Ratio 1:15–1:18 | Extraction 18–22% | TDS 1.15–1.35%','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var coffee=parseFloat(document.getElementById("in-coffee").value)||1,water=parseFloat(document.getElementById("in-water").value)||1,method=document.getElementById("in-method").value,grind=document.getElementById("in-grind").value,temp=parseFloat(document.getElementById("in-temp").value)||96,tds=parseFloat(document.getElementById("in-tds").value)||1.35;var ratio=water/coffee;var brewedWater=water*0.94;var extraction=(brewedWater*tds/100)/coffee*100;var ideal={pourover:{r:"1:15-1:17",g:"Medium",t:"92-96"},french:{r:"1:15-1:17",g:"Coarse",t:"93-96"},espresso:{r:"1:1.5-1:2.5",g:"Fine",t:"90-94"},aeropress:{r:"1:12-1:16",g:"Medium-Fine",t:"85-96"}};var rec=ideal[method];document.getElementById("out-main").textContent="1:"+ratio.toFixed(1);document.getElementById("out-unit").textContent="Brew Ratio";document.getElementById("out-detail").innerHTML=\'<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Ratio</div><div class="h5 fw-bold mb-0 text-primary">1:\'+ratio.toFixed(1)+\'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Extraction</div><div class="h5 fw-bold mb-0 text-info">\'+extraction.toFixed(1)+\'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">TDS</div><div class="h5 fw-bold mb-0 text-success">\'+tds+\'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Temp</div><div class="h5 fw-bold mb-0 text-warning">\'+temp+\'°C</div></div></div>\';var ins=["Brew ratio: <b>1:"+ratio.toFixed(1)+"</b> (ideal for "+method+": "+rec.r+")","Extraction yield: <b>"+extraction.toFixed(1)+"%</b> (SCA target: 18-22%)"];if(extraction<18)ins.push("⚠ Under-extracted — try finer grind or longer brew time");else if(extraction>22)ins.push("⚠ Over-extracted — try coarser grind or shorter time");ins.push("Recommended grind: <b>"+rec.g+"</b> | Temp: <b>"+rec.t+"°C</b>");document.getElementById("out-ins").innerHTML=\'<ul class="list-unstyled mb-0">\'+ins.map(function(x){return\'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>\'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-coffee").value=18;document.getElementById("in-water").value=300;document.getElementById("in-temp").value=96;document.getElementById("in-tds").value=1.35;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Ratio: "+document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
